class Aria2{#url;#secret;#socket;#id=0;#tries=0;#retries=10;#timeout=1e4;#timer;#pending=new Map;#onopen=null;#onmessage=null;#onclose=null;#ready=false;constructor(url,secret){if(!url){this.url="ws://localhost:6800/jsonrpc";this.secret=""}else{let i=url.indexOf("#");if(i!==-1){this.url=url.substring(0,i);this.secret=url.substring(i+1)}else{this.url=url;this.secret=secret||""}}}set url(string){if(string.startsWith("http://")||string.startsWith("https://")){this.#url="ws"+string.substring(4)}else if(string.startsWith("ws://")||string.startsWith("wss://")){this.#url=string}else{throw new TypeError("Invalid URL: expected a valid ws(s):// URL")}}get url(){return this.#url}set secret(string){this.#secret="token:"+string}get secret(){return this.#secret.substring(6)}set retries(number){let n=number|0;if(n<0){this.#retries=Infinity}else{this.#retries=n}}get retries(){return this.#retries}set timeout(number){let n=number|0;if(n>1){this.#timeout=n*1e3}else{this.#timeout=1e3}}get timeout(){return this.#timeout/1e3}set onopen(callback){if(typeof callback==="function"){this.#onopen=callback}else{this.#onopen=null}}get onopen(){return this.#onopen}set onmessage(callback){if(typeof callback==="function"){this.#onmessage=callback}else{this.#onmessage=null}}get onmessage(){return this.#onmessage}set onclose(callback){if(typeof callback==="function"){this.#onclose=callback}else{this.#onclose=null}}get onclose(){return this.#onclose}#open(){let socket=this.#socket;let url=this.#url;if(socket){let readyState=socket.readyState;if(socket.url===url){if(readyState===0){throw new Error("WebSocket error: connection is still in CONNECTING state")}if(readyState===1){return}}socket.onopen=null;socket.onmessage=null;socket.onclose=null;socket.close()}socket=new WebSocket(url);this.#socket=socket;socket.onopen=event=>{this.#ready=true;this.#tries=0;let onopen=this.#onopen;if(onopen){onopen(event)}};socket.onmessage=event=>{let json=JSON.parse(event.data);let id=json.id;if(id!==undefined){let pending=this.#pending;let session=pending.get(id);if(session){pending.delete(id);session.resolve(json)}}else{let onmessage=this.#onmessage;if(onmessage){onmessage(json)}}};socket.onclose=event=>{this.#ready=false;let pending=this.#pending;if(pending.size>0){for(let session of pending.values()){session.reject(new Error("WebSocket error: connection closed"))}pending.clear()}let onclose=this.#onclose;if(onclose){onclose(event)}if(this.#tries++<this.#retries){this.#timer=setTimeout(()=>this.#open(),this.#timeout)}else{this.#tries=0}}}#send(json){return new Promise((resolve,reject)=>{if(!this.#ready){throw new Error("WebSocket error: failed to send message")}this.#pending.set(json.id,{resolve:resolve,reject:reject});this.#socket.send(JSON.stringify(json))})}call(method,params){if(params){params=[this.#secret].concat(params)}else{params=[this.#secret]}return this.#send({jsonrpc:"2.0",id:this.#id++,method:method,params:params})}multicall(args){let calls=[];let secret=this.#secret;for(let i=0,l=args.length;i<l;i++){let arg=args[i];let params=arg.params;if(params){params=[secret].concat(params)}else{params=[secret]}calls[i]={methodName:arg.methodName,params:params}}return this.#send({jsonrpc:"2.0",id:this.#id++,method:"system.multicall",params:[calls]})}connect(){clearTimeout(this.#timer);this.#tries=0;this.#open()}disconnect(){clearTimeout(this.#timer);this.#tries=Infinity;if(this.#ready){this.#socket.close()}}}